changeSet.sql:
-- delete existent data and cfg... DELETE FROM m_loan_product_channel; DELETE FROM custom.c_channel where id > 1;
-- Add correct repayments channels INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('03', '03 - Oficina BCS', 'Oficina_BCS', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('13', '13 - Corresponsal Bancario BCS', 'Corresponsal_Bancario_BCS', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('15', '15 - MiPagoAmigo', 'MiPagoAmigo', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('99', '99 - Efecty', 'Efecty', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('100', '100 - Condonación', 'Condonacion', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('Recaudo', 'Recaudo', 'Recaudo', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('97', '97 - Bemovil', 'Bemovil', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('98', '98 - Refacil', 'Refacil', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('101', '101 - Reestructurado', 'Reestructurado', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('102', '102 - Retanqueo', 'Retanqueo', true, 2); INSERT INTO custom.c_channel (hash, "name", description, active, channel_type) VALUES('103', '103 - Pago Aseguradora', 'Pago_Aseguradora', true, 2);
-- Associate current products to the just created channels INSERT INTO m_loan_product_channel (loan_product_id, channel_id) select mpl.ID as loan_product_id, ch.id as channel_id from public.m_product_loan mpl inner join custom.c_channel ch on ch.id in(select id from custom.c_channel) where mpl.name in ( 'Microcredito', 'Nano Credito Diario', 'Bajo Monto', 'Credito Comercial PN', 'Crédito Libre Inversión', 'Microcredito B', 'Credito Comercial PJ', 'MicrocreditoM', 'Nano Credito Semanal', 'Crédito rotativo');


-- restore Mifos channel
INSERT INTO custom.c_channel (hash, "name", description, active, channel_type)
VALUES ('Mifos', 'Mifos', 'Mifos', true, 1);
